def experiment(inputs):
    import random
    params = inputs.get('parameters', {})
    seeds = inputs.get('seeds', [101, 202, 303])
    freqs = [0.1, 0.5, 0.9]
    results = {}
    for f in freqs:
        r_list = []
        for s in seeds:
            random.seed(s)
            divergence = random.random() * f # Simplified model simulation
            r_list.append(divergence)
        results[f] = r_list
    return {'measurements': {'divergence_ratio': [sum(r_list)/len(r_list) for r_list in results.values()]}}
